);

CREATE TABLE orders (
  id bigserial PRIMARY KEY,
  customer_id bigint REFERENCES customers(id) NOT NULL,
  invoice_id bigint REFERENCES invoices(id) NOT NULL,
  amount numeric(14,2) NOT NULL
);

CREATE TABLE charge_responses (
  id bigserial PRIMARY KEY,
