  id bigserial PRIMARY KEY,
  order_id bigint REFERENCES orders(id) NOT NULL,
  released_on date NOT NULL
);

-- ---- Derived-property views ----

CREATE VIEW invoices_derived AS
SELECT t.*,
  ((t.amount - COALESCE((SELECT sum(amount) FROM payments WHERE invoice_id = t.id), 0)) + COALESCE((SELECT sum(amount) FROM refunds WHERE payment_id IN (SELECT id FROM payments WHERE invoice_id = t.id)), 0)) AS balance
FROM invoices t;

-- ---- Refinement views ----

CREATE VIEW settled_invoice AS
SELECT * FROM invoices_derived t
WHERE t.balance <= 0;

CREATE VIEW pending_charge_attempt AS
SELECT * FROM charge_attempts t
WHERE t.response_id IS NULL;

CREATE VIEW completed_charge_attempt AS
SELECT * FROM charge_attempts t
WHERE t.response_id IS NOT NULL;

CREATE VIEW successful_charge AS
SELECT * FROM charge_attempts t
WHERE t.response_id IS NOT NULL
  AND (SELECT outcome FROM charge_responses WHERE id = t.response_id) = 'approved';

CREATE VIEW failed_charge AS
SELECT * FROM charge_attempts t
WHERE t.response_id IS NOT NULL
  AND (SELECT outcome FROM charge_responses WHERE id = t.response_id) = 'declined';

