-- ---- Entering-refinement triggers ----

CREATE OR REPLACE FUNCTION trg_orders_check() RETURNS trigger AS $$
DECLARE
  affected_id bigint;
BEGIN
    affected_id := NEW.id;
    IF affected_id IS NOT NULL
       AND TRUE
       AND NOT EXISTS (SELECT 1 FROM charge_attempts WHERE order_id = affected_id)
    THEN
      INSERT INTO effects_outbox (effect_name, payload)
      VALUES ('InitiateCharge', jsonb_build_object('root_id', affected_id));
    END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER orders_after_write
AFTER INSERT OR UPDATE ON orders
FOR EACH ROW EXECUTE FUNCTION trg_orders_check();

