DECLARE
  affected_id bigint;
BEGIN
    affected_id := NEW.id;
    IF affected_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM successful_charge WHERE id = affected_id)
       AND NOT EXISTS (SELECT 1 FROM payments WHERE charge_attempt_id = affected_id)
    THEN
      INSERT INTO effects_outbox (effect_name, payload)
      VALUES ('RecordPayment', jsonb_build_object('root_id', affected_id));
    END IF;
    affected_id := NEW.id;
    IF affected_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM failed_charge WHERE id = affected_id)
       AND NOT EXISTS (SELECT 1 FROM inventory_releases WHERE order_id = affected_id)
    THEN
      INSERT INTO effects_outbox (effect_name, payload)
      VALUES ('ReleaseInventory', jsonb_build_object('root_id', affected_id));
    END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

